import {
  Background,
  BackgroundVariant,
  Controls,
  MiniMap,
  ReactFlow,
  ReactFlowProvider,
} from "@xyflow/react"

import "@xyflow/react/dist/style.css"

import { useTheme } from "@/components/theme/use-theme"
import { cn } from "@/lib/utils"
import { reactFlowNodeTypes } from "@/components/ui/react-flow-node-types"
import type { ReactFlowDiagramProps } from "@/components/ui/react-flow-types"

/**
 * ReactFlowDiagram — suite de diagramas (React Flow / @xyflow/react)
 * padronizada para a vitrine shadcn.
 *
 * - Embrulha `ReactFlowProvider` + `ReactFlow` num container com altura fixa.
 * - `colorMode={resolvedTheme}` alterna a base clara/escura do React Flow;
 *   o ajuste fino vem dos overrides de token `--xy-*` em `src/index.css`.
 * - Background/Controls/MiniMap são opt-out via props booleanas.
 */
function ReactFlowDiagram({
  nodes,
  edges,
  onNodesChange,
  onEdgesChange,
  onConnect,
  nodeTypes = reactFlowNodeTypes,
  edgeTypes,
  fitView = true,
  showMiniMap = true,
  showControls = true,
  showBackground = true,
  nodesDraggable = true,
  nodesConnectable = true,
  className,
  ...rest
}: ReactFlowDiagramProps) {
  const { resolvedTheme } = useTheme()

  return (
    <div
      data-slot="react-flow"
      className={cn(
        "h-[500px] w-full overflow-hidden rounded-lg border border-border bg-background",
        className,
      )}
      {...rest}
    >
      <ReactFlowProvider>
        <ReactFlow
          colorMode={resolvedTheme}
          nodes={nodes}
          edges={edges}
          onNodesChange={onNodesChange}
          onEdgesChange={onEdgesChange}
          onConnect={onConnect}
          nodeTypes={nodeTypes}
          edgeTypes={edgeTypes}
          fitView={fitView}
          nodesDraggable={nodesDraggable}
          nodesConnectable={nodesConnectable}
          proOptions={{ hideAttribution: true }}
        >
          {showBackground ? (
            <Background variant={BackgroundVariant.Dots} gap={16} size={1} />
          ) : null}
          {showControls ? <Controls /> : null}
          {showMiniMap ? <MiniMap pannable zoomable /> : null}
        </ReactFlow>
      </ReactFlowProvider>
    </div>
  )
}

export { ReactFlowDiagram }

import type { NodeTypes } from "@xyflow/react"

import { ShadcnCardNode } from "@/components/ui/react-flow-nodes"

/** `nodeTypes` default — registra o node shadcn sob a chave `"shadcn"`. */
export const reactFlowNodeTypes: NodeTypes = {
  shadcn: ShadcnCardNode,
}

import { Handle, Position, type NodeProps } from "@xyflow/react"

import { cn } from "@/lib/utils"
import type { ShadcnNode } from "@/components/ui/react-flow-types"

/**
 * Node customizado no estilo shadcn: um cartão com `bg-card`/`border-border`,
 * título, descrição e badge opcional. Handles tematizados com `bg-primary`.
 */
function ShadcnCardNode({ data, selected }: NodeProps<ShadcnNode>) {
  return (
    <div
      data-slot="react-flow-node"
      className={cn(
        "min-w-44 max-w-64 rounded-lg border border-border bg-card px-4 py-3 text-card-foreground shadow-sm transition-shadow",
        selected && "ring-2 ring-ring",
      )}
    >
      <Handle
        type="target"
        position={Position.Top}
        className="!size-2.5 !border-2 !border-background !bg-primary"
      />
      <div className="flex items-start justify-between gap-2">
        <p className="text-sm font-semibold leading-tight">{data.label}</p>
        {data.badge ? (
          <span className="shrink-0 rounded-full bg-primary/10 px-2 py-0.5 text-[10px] font-medium uppercase tracking-wide text-primary">
            {data.badge}
          </span>
        ) : null}
      </div>
      {data.description ? (
        <p className="mt-1 text-xs leading-snug text-muted-foreground">
          {data.description}
        </p>
      ) : null}
      <Handle
        type="source"
        position={Position.Bottom}
        className="!size-2.5 !border-2 !border-background !bg-primary"
      />
    </div>
  )
}

export { ShadcnCardNode }

import type {
  Edge,
  EdgeTypes,
  Node,
  NodeTypes,
  OnConnect,
  OnEdgesChange,
  OnNodesChange,
} from "@xyflow/react"

/**
 * Props do wrapper `ReactFlowDiagram` — suite de diagramas tematizada shadcn.
 *
 * Embrulha `ReactFlowProvider` + `ReactFlow`, expõe controles booleanos para
 * Background/Controls/MiniMap e repassa o restante das props ao container raiz.
 */
export type ReactFlowDiagramProps = Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "children"
> & {
  /** Nós do grafo. */
  nodes: Node[]
  /** Arestas do grafo. */
  edges: Edge[]
  /** Handler de mudança de nós (drag, seleção, remoção). */
  onNodesChange?: OnNodesChange
  /** Handler de mudança de arestas. */
  onEdgesChange?: OnEdgesChange
  /** Handler de conexão (ao ligar dois handles). */
  onConnect?: OnConnect
  /** Mapa de tipos de nós customizados. */
  nodeTypes?: NodeTypes
  /** Mapa de tipos de arestas customizadas. */
  edgeTypes?: EdgeTypes
  /** Ajusta a viewport para enquadrar todo o grafo. Default: `true`. */
  fitView?: boolean
  /** Exibe o MiniMap (canto inferior direito). Default: `true`. */
  showMiniMap?: boolean
  /** Exibe os Controls (zoom/fit/lock). Default: `true`. */
  showControls?: boolean
  /** Exibe o Background pontilhado. Default: `true`. */
  showBackground?: boolean
  /** Permite arrastar nós. Default: `true`. */
  nodesDraggable?: boolean
  /** Permite criar conexões. Default: `true`. */
  nodesConnectable?: boolean
}

/** Formato do `data` do nó shadcn customizado. */
export type ShadcnNodeData = {
  /** Título em destaque do node. */
  label: string
  /** Subtítulo/descrição opcional. */
  description?: string
  /** Texto curto de badge opcional (canto superior). */
  badge?: string
}

export type ShadcnNode = Node<ShadcnNodeData, "shadcn">
